ALTER proc [dbo].[SIM_TeachingTimeAdded_UpdateReview]
(
	@TeachingTimeAddedID bigint,
	@IsReviewed bit,
	@ReviewedDate datetime,
	@ReviewedUser nvarchar(50),
	@ReviewedComment nvarchar(500),
	@UpdatedUser nvarchar(50)
)
AS
Begin

	Update SIM_TeachingTimeAdded
	Set
		IsReviewed = @IsReviewed,
		ReviewedDate = @ReviewedDate,
		ReviewedUser = @ReviewedUser,
		ReviewedComment = @ReviewedComment,
		UpdatedUser = @UpdatedUser,
		UpdatedDate = getdate()
	Where TeachingTimeAddedID = @TeachingTimeAddedID

End

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using WebGlobal;
using SimsObject;

namespace InformationWeb.Controls.TeacherWork
{
    /// <summary>
    /// Trang quản lý duyệt công việc khác
    /// </summary>
    public partial class ReviewList : ControlBase
    {

        #region Properties

        private string SortBy
        {
            set { ViewState["SortBy"] = value; }
            get
            {
                if (ViewState["SortBy"] != null) return ViewState["SortBy"].ToString();
                return null;
            }
        }

        private string SortDesc
        {
            set { ViewState["SortDesc"] = value; }
            get
            {
                if (ViewState["SortDesc"] != null) return ViewState["SortDesc"].ToString();
                return null;
            }
        }

        #endregion

        protected int intRowIndex = 0;

        private void LoadData(string sortExpression, object teacherID)
        {
            if (User == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            if (uYearSemester.YearID == null || uYearSemester.Semester == null)
            {
                MsgBox.ShowError("Bạn phải chọn niên, kỳ!");
                return;
            }

            SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
            DataTable dtbData = obj.GetDataTable("SIM_TeachingTimeAdded_Reviewed",
                                        "@YearID", uYearSemester.YearID,
                                        "@Semester", uYearSemester.Semester,
                                        "@TeacherID", teacherID);

            if (dtbData != null)
            {
                if (sortExpression == null && this.SortBy != null && this.SortDesc != null)
                {
                    sortExpression = this.SortBy + " " + this.SortDesc;
                }

                dtbData.DefaultView.Sort = sortExpression;
                intRowIndex = 0;
                rptList.DataSource = dtbData;
                rptList.DataBind();
                ModifyGrid();
                udpList.Update();
            }
            else
            {
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
            }
        }

        private void ModifyGrid()
        {
            string strChecked = "";
            List<string> lstCheckedList = new List<string>();
            try
            {
                string strCheckedList = Request["iptSelectReview"] != null ? Convert.ToString(Request["iptSelectReview"]) : "";
                if (strCheckedList != "")
                    lstCheckedList = new List<string>(strCheckedList.Split(','));
            }
            catch
            {
            }

            foreach (RepeaterItem item in rptList.Items)
            {
                Label lblCheckbox = item.FindControl("lblCheckbox") as Label;
                if (lblCheckbox == null || !lblCheckbox.Visible)
                    continue;

                lblCheckbox.ToolTip = lblCheckbox.Text;
                if (lstCheckedList.Contains(lblCheckbox.ToolTip))
                    strChecked = "checked='checked'";
                else
                    strChecked = "";

                lblCheckbox.Text = "<input id='iptSelectReview' name='iptSelectReview' value='" + lblCheckbox.ToolTip + "' " + strChecked + " onclick='Item_Select(\"selectall\", \"iptSelectReview\");' type='checkbox' />";
            }
        }

        private bool SaveReview()
        {
            string arrID = Request["iptSelectReview"];
            if (arrID == null || arrID.Trim() == "")
            {
                MsgBox.ShowWarning("Bạn phải chọn ít nhất một công việc để duyệt!");
                return false;
            }

            SIM_TeachingTimeAdded obj = new SIM_TeachingTimeAdded();
            obj.BeginTransaction();

            int intCount = 0;
            string[] arrSelectedID = arrID.Split(',');
            foreach (RepeaterItem item in rptList.Items)
            {
                HiddenField hidTeachingTimeAddedID = item.FindControl("hidTeachingTimeAddedID") as HiddenField;
                if (hidTeachingTimeAddedID == null || hidTeachingTimeAddedID.Value == "")
                    continue;

                string strID = hidTeachingTimeAddedID.Value;
                bool bolSelected = false;
                for (int i = 0; i < arrSelectedID.Length; i++)
                {
                    if (arrSelectedID[i].Trim() == strID)
                    {
                        bolSelected = true;
                        break;
                    }
                }

                if (!bolSelected)
                    continue;

                TextBox txtReviewedComment = item.FindControl("txtReviewedComment") as TextBox;
                string strComment = "";
                if (txtReviewedComment != null)
                    strComment = txtReviewedComment.Text.Trim();

                if (!obj.ExecNonQuery("SIM_TeachingTimeAdded_UpdateReview",
                    "@TeachingTimeAddedID", Convert.ToInt64(strID),
                    "@IsReviewed", true,
                    "@ReviewedDate", DateTime.Now,
                    "@ReviewedUser", User.UserName,
                    "@ReviewedComment", strComment,
                    "@UpdatedUser", User.UserName))
                {
                    MsgBox.ShowError("Việc cập nhật duyệt bị lỗi! " + obj.ErrorException.Message);
                    return false;
                }
                intCount++;
            }

            obj.CommitTransaction();
            MsgBox.ShowInfo("Đã duyệt thành công! Số dòng: " + intCount);

            string strActionLog = "Năm học: " + uYearSemester.YearText + " - HK: " + uYearSemester.Semester;
            new SystemObject.SYS_ActionLog().WriteActionLog("Quản lý duyệt công việc khác trên web", strActionLog, SystemObject.ActionLogType.EDIT, intCount, User.UserName);

            return true;
        }

        #region Protected Functions

        protected string GetCssName(string fieldName)
        {
            if (this.SortBy == fieldName)
            {
                if (this.SortDesc == "Desc")
                    return "Title-Desc";
                return "Title-Asc";
            }
            return "";
        }

        protected string WriteEventRow()
        {
            intRowIndex++;
            if (intRowIndex % 2 == 0)
                return " class='RowAlt' ";
            return " class='Row' ";
        }

        protected bool IsTrue(object bol)
        {
            if (bol != null && bol.ToString() != "")
                return Convert.ToBoolean(bol);
            return false;
        }

        protected bool AllowSelect(object isReviewed)
        {
            return !IsTrue(isReviewed);
        }

        protected string FormatReviewStatus(object isReviewed)
        {
            if (IsTrue(isReviewed))
                return "<span style='color:Green;font-weight:bold'>Đã duyệt</span>";
            return "<span style='color:OrangeRed'>Chưa duyệt</span>";
        }

        protected string GetStandardHours(object requestTotal, object teacherWorkId)
        {
            if (requestTotal == null || requestTotal == DBNull.Value)
                return "";

            if (teacherWorkId == null || teacherWorkId == DBNull.Value)
                return "";

            decimal? total = WebGlobal.ToDecimal(requestTotal);
            if (total == null)
                return "";

            int workId = Convert.ToInt32(teacherWorkId);
            decimal result = 0;

            if (workId == 35)
                result = total.Value * 52 / 160;
            else if (workId == 34)
                result = total.Value * 26 / 80;
            else
                return "";

            return result.ToString("0.##");
        }

        #endregion

        protected void Page_Load(object sender, EventArgs e)
        {
            uYearSemester.EditValueChanged += new Sims.UYearSemester2.EditValueChangedDelegate(uYearSemester_EditValueChanged);
            uTeacher.SearchClick += new Sims.UTeacher2.SearchDelegate(SearchClick);

            if (!IsPostBack)
            {
                if (User == null)
                {
                    MsgBox.ShowWarning("Chức năng này chỉ dành cho nhà quản lý, vui lòng đăng nhập!");
                    Response.Redirect("~/");
                }

                uYearSemester.LoadData();
            }
        }

        private void uYearSemester_EditValueChanged(object yearID, object semester)
        {
        }

        private void SearchClick(object scienceID, object subjectGroupID, object teacherID)
        {
            if (uYearSemester.YearID != null && uYearSemester.Semester != null)
                LoadData(null, teacherID);
        }

        protected void lbtTitle_Click(object sender, EventArgs e)
        {
            LinkButton lbt = sender as LinkButton;
            this.SortBy = lbt.CommandArgument;
            if (this.SortDesc == "Asc")
                this.SortDesc = "Desc";
            else
                this.SortDesc = "Asc";

            object teacherID = uTeacher.TeacherID;
            if (teacherID != null && teacherID.ToString() == "")
                teacherID = null;
            LoadData(null, teacherID);
        }

        protected void btnApprove_Click(object sender, EventArgs e)
        {
            if (SaveReview())
            {
                object teacherID = uTeacher.TeacherID;
                if (teacherID != null && teacherID.ToString() == "")
                    teacherID = null;
                LoadData(null, teacherID);
            }
        }
    }
}

